mapper.delete:
	DELETE 
	FROM notice_files
	WHERE notice_file_id = #{noticeFileId}
		 AND notice_id = #{noticeId}
		 AND EXISTS (
		 	 SELECT 1
		 	 FROM notice 
		 	 WHERE workspace_id = #{workspaceId}
		 	 	AND notice_id = #{noticeId}
		 	 	AND notice_type = 'WORKSPACE'
		 	 	AND status = 1
		 	 	AND deleted IS NULL
    )

mapper.update:
UPDATE notice SET view_count = view_count + 1
WHERE workspace_id = #{workspaceId}
	AND notice_id = #{noticeId}
	AND notice_type = 'WORKSPACE'
	AND status = 1
	AND deleted IS NULL
